import { test, expect } from '@playwright/test';

test.describe('Touch Target Size Accessibility', () => {
  const MINIMUM_TOUCH_TARGET_SIZE = 44; // pixels (WCAG 2.5.5 Level AAA standard)

  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    await page.goto('https://example.com');
  });

  test('should have touch targets with minimum 44x44 pixel size for buttons', async ({ page }) => {
    // Get all buttons on the page
    const buttons = await page.getByRole('button').all();

    expect(buttons.length).toBeGreaterThan(0);

    for (const button of buttons) {
      const boundingBox = await button.boundingBox();

      expect(boundingBox).not.toBeNull();

      if (boundingBox) {
        expect(boundingBox.width).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);
        expect(boundingBox.height).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);
      }
    }
  });

  test('should have touch targets with minimum 44x44 pixel size for links', async ({ page }) => {
    // Get all interactive links on the page
    const links = await page.getByRole('link').all();

    expect(links.length).toBeGreaterThan(0);

    for (const link of links) {
      const boundingBox = await link.boundingBox();

      expect(boundingBox).not.toBeNull();

      if (boundingBox) {
        expect(boundingBox.width).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);
        expect(boundingBox.height).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);
      }
    }
  });

  test('should have adequate spacing between touch targets', async ({ page }) => {
    const buttons = await page.getByRole('button').all();
    const MINIMUM_SPACING = 8; // pixels between touch targets

    for (let i = 0; i < buttons.length - 1; i++) {
      const currentBox = await buttons[i].boundingBox();
      const nextBox = await buttons[i + 1].boundingBox();

      if (currentBox && nextBox) {
        // Check horizontal spacing if buttons are on the same row
        if (Math.abs(currentBox.y - nextBox.y) < 10) {
          const horizontalGap = nextBox.x - (currentBox.x + currentBox.width);
          expect(horizontalGap).toBeGreaterThanOrEqual(MINIMUM_SPACING);
        }

        // Check vertical spacing if buttons are in different rows
        if (currentBox.x !== nextBox.x) {
          const verticalGap = nextBox.y - (currentBox.y + currentBox.height);
          expect(verticalGap).toBeGreaterThanOrEqual(MINIMUM_SPACING);
        }
      }
    }
  });

  test('should have touch targets with minimum 44x44 pixel size for form inputs', async ({ page }) => {
    // Get all form inputs (checkboxes, radio buttons, etc.)
    const checkboxes = await page.getByRole('checkbox').all();
    const radioButtons = await page.getByRole('radio').all();
    const allInputs = [...checkboxes, ...radioButtons];

    for (const input of allInputs) {
      const boundingBox = await input.boundingBox();

      if (boundingBox) {
        expect(boundingBox.width).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);
        expect(boundingBox.height).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);
      }
    }
  });

  test('should ensure touch targets are easily tappable without zooming', async ({ page }) => {
    // Verify viewport is set to mobile size
    const viewportSize = page.viewportSize();
    expect(viewportSize?.width).toBeLessThanOrEqual(480); // Mobile width threshold

    // Get primary action button
    const primaryButton = page.getByRole('button', { name: /submit|send|confirm/i }).first();

    if (await primaryButton.isVisible()) {
      const boundingBox = await primaryButton.boundingBox();

      expect(boundingBox).not.toBeNull();

      if (boundingBox) {
        // Verify button is large enough and positioned within safe tap zone
        expect(boundingBox.width).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);
        expect(boundingBox.height).toBeGreaterThanOrEqual(MINIMUM_TOUCH_TARGET_SIZE);

        // Verify button is not too close to viewport edges
        const EDGE_MARGIN = 8;
        expect(boundingBox.x).toBeGreaterThanOrEqual(EDGE_MARGIN);
        expect(boundingBox.y).toBeGreaterThanOrEqual(EDGE_MARGIN);
      }
    }
  });
});
